//! Taking out of a tool's schema what says nothing to a model.
//!
//! A tool definition is JSON Schema, and JSON Schema generated by a library
//! carries bookkeeping: the dialect it was written in, an identifier, a
//! `title` that repeats the property's own name. The provider renders all of
//! it into the prompt on every request. `proxy.tools_compact` removes that
//! and nothing else.
//!
//! # What is removed
//!
//! - `$schema` and `$comment`. The first names a dialect for a validator; the
//!   second is, by the specification, to be ignored.
//! - A root `$id`, when nothing in the schema refers outside it. It names the
//!   schema for other documents to point at.
//! - `markdownDescription` beside a `description`: an editor's rendering of
//!   the same text.
//! - A `title` that only restates the name of the property it sits on
//!   (`"file_path"` titled `"File Path"`), or, at the root, the name of the
//!   tool. This is what a schema generated from a typed model is full of.
//!
//! # What is not
//!
//! Anything a model might act on: descriptions, `examples`, `deprecated`,
//! `default`, `enum`, `const`, formats and constraints, a `title` that says
//! something its name does not. Nothing is reworded, shortened, sorted or
//! re-spaced, and nothing inside a `default`, `enum` or `const` *value* is
//! looked at — a default that happens to be an object with a `$schema` key is
//! the tool's data. Headroom's compaction goes further (it drops `examples`
//! and can truncate descriptions); with no way to hand the removed text back,
//! this stops where the loss stops being arguable.
//!
//! # Why it has to be decided once
//!
//! The tool block sits at the front of the cached prefix, so its bytes must
//! not change during a conversation. The transform is a pure function of one
//! tool definition, which gives the same bytes every turn — but only if every
//! turn applies it. [`ToolPolicies`] therefore fixes the answer when a
//! conversation is first seen and keeps it whatever the configuration later
//! says, and a conversation first seen part-way through, whose tools the
//! provider already holds as the client wrote them, is never compacted.

use std::collections::HashMap;
use std::sync::Mutex;
use std::time::Instant;

use serde_json::{Map, Value};

use crate::drift::tool_name;
use crate::tool::RETRIEVE_TOOL_NAME;

/// Conversations remembered, the same bound the prefix tracker keeps.
const REMEMBER: usize = 4096;

/// A conversation seen for the first time with more messages than this was
/// under way before this proxy saw it.
pub(crate) const OPENING_MESSAGES: usize = 2;

/// Suffixes a generator puts on a tool's name to title its argument model.
const ROOT_TITLE_SUFFIXES: [&str; 8] = [
    "",
    "arguments",
    "args",
    "input",
    "params",
    "parameters",
    "request",
    "schema",
];

/// Letters and digits only, lower-cased: `file_path`, `File Path` and
/// `filePath` are one name.
fn bare(name: &str) -> String {
    name.chars()
        .filter(|c| c.is_alphanumeric())
        .flat_map(char::to_lowercase)
        .collect()
}

/// Whether `title` is only one of `names` in another spelling: the same
/// letters and digits, with nothing between them but spaces, `_` and `-`.
/// Anything else in it — `C++` on a property named `c`, `I/O` on `io` — is
/// something the name does not say.
fn restates(title: &str, names: &[String]) -> bool {
    title
        .chars()
        .all(|c| c.is_alphanumeric() || c.is_whitespace() || c == '_' || c == '-')
        && names.contains(&bare(title))
}

/// Whether anything under `value` refers to a schema outside this document.
fn refers_outside(value: &Value) -> bool {
    match value {
        Value::Object(object) => object.iter().any(|(key, item)| {
            (key == "$ref" && item.as_str().is_some_and(|target| !target.starts_with('#')))
                || refers_outside(item)
        }),
        Value::Array(items) => items.iter().any(refers_outside),
        _ => false,
    }
}

fn removed(object: &mut Map<String, Value>, key: &str) -> bool {
    // `shift_remove`, not `remove`: with `preserve_order` the latter swaps the
    // last key into the hole, and key order is the client's.
    object.shift_remove(key).is_some()
}

/// Compact one schema in place. `named` is what a `title` here would have to
/// restate to be noise: the property's name, or at the root every title a
/// generator derives from the tool's name.
fn compact_schema(schema: &mut Value, named: &[String], root: Option<bool>) -> bool {
    let Some(object) = schema.as_object_mut() else {
        return false;
    };
    let mut changed = removed(object, "$comment");
    if let Some(keep_id) = root {
        changed |= removed(object, "$schema");
        if !keep_id {
            changed |= removed(object, "$id");
        }
    }
    if object.get("description").is_some_and(Value::is_string) {
        changed |= removed(object, "markdownDescription");
    }
    if object
        .get("title")
        .and_then(Value::as_str)
        .is_some_and(|title| restates(title, named))
    {
        changed |= removed(object, "title");
    }

    for (key, item) in object.iter_mut() {
        match key.as_str() {
            // Maps from a name to a schema: the keys are names, not keywords.
            "properties" => {
                if let Some(properties) = item.as_object_mut() {
                    for (name, property) in properties.iter_mut() {
                        changed |= compact_schema(property, &[bare(name)], None);
                    }
                }
            }
            "patternProperties" | "$defs" | "definitions" | "dependentSchemas" => {
                if let Some(schemas) = item.as_object_mut() {
                    for schema in schemas.values_mut() {
                        changed |= compact_schema(schema, &[], None);
                    }
                }
            }
            // A schema.
            "items"
            | "additionalProperties"
            | "additionalItems"
            | "not"
            | "if"
            | "then"
            | "else"
            | "contains"
            | "propertyNames"
            | "unevaluatedItems"
            | "unevaluatedProperties" => {
                // `items` may also be a list of schemas, in older dialects.
                if let Some(schemas) = item.as_array_mut() {
                    for schema in schemas {
                        changed |= compact_schema(schema, &[], None);
                    }
                } else {
                    changed |= compact_schema(item, &[], None);
                }
            }
            // A list of schemas.
            "allOf" | "anyOf" | "oneOf" | "prefixItems" => {
                if let Some(schemas) = item.as_array_mut() {
                    for schema in schemas {
                        changed |= compact_schema(schema, &[], None);
                    }
                }
            }
            // Everything else is a value: a default, an enum, a constraint, or
            // a keyword this does not know. Not looked into.
            _ => {}
        }
    }
    changed
}

/// Where a tool definition keeps its schema, in each family's spelling.
fn schema_of(tool: &mut Value) -> Option<&mut Value> {
    let object = tool.as_object_mut()?;
    if object.contains_key("input_schema") {
        return object.get_mut("input_schema");
    }
    if object.get("function").is_some_and(Value::is_object) {
        return object.get_mut("function")?.get_mut("parameters");
    }
    object.get_mut("parameters")
}

/// Compact one tool definition in place. Returns whether it changed.
///
/// A pure function of the definition: the same tool compacts to the same
/// bytes on every request, in every process.
pub(crate) fn compact_tool(tool: &mut Value) -> bool {
    let name = bare(tool_name(tool));
    let named: Vec<String> = if name.is_empty() {
        Vec::new()
    } else {
        ROOT_TITLE_SUFFIXES
            .iter()
            .map(|suffix| format!("{name}{suffix}"))
            .collect()
    };
    let Some(schema) = schema_of(tool) else {
        return false;
    };
    let keep_id = refers_outside(schema);
    compact_schema(schema, &named, Some(keep_id))
}

/// Compact every tool the client declared. Returns how many changed.
///
/// The retrieve tool this proxy adds is left alone: it is written compact.
pub(crate) fn compact_tools(tools: &mut [Value]) -> usize {
    tools
        .iter_mut()
        .filter(|tool| tool_name(tool) != RETRIEVE_TOOL_NAME)
        .map(|tool| usize::from(compact_tool(tool)))
        .sum()
}

/// Whether each conversation's tools are compacted, decided once.
#[derive(Default)]
pub struct ToolPolicies {
    decided: Mutex<HashMap<u64, (Instant, bool)>>,
}

impl ToolPolicies {
    /// Whether to compact this conversation's tools.
    ///
    /// Decided on the first request this process sees of it and never again:
    /// `configured` then, and `false` for a conversation that was already
    /// `messages` long — past [`OPENING_MESSAGES`] — when it arrived. Later
    /// requests get the same answer whatever `configured` has become.
    pub(crate) fn compacting(&self, conversation: u64, messages: usize, configured: bool) -> bool {
        let Ok(mut decided) = self.decided.lock() else {
            return false;
        };
        if let Some((used, policy)) = decided.get_mut(&conversation) {
            // Refreshed on every use: what is evicted at the cap is the
            // conversation idle longest, never one still under way, whose next
            // request would be decided afresh and against it.
            *used = Instant::now();
            return *policy;
        }
        if decided.len() >= REMEMBER
            && let Some(oldest) = decided
                .iter()
                .min_by_key(|(_, (at, _))| *at)
                .map(|(key, _)| *key)
        {
            decided.remove(&oldest);
        }
        let policy = configured && messages <= OPENING_MESSAGES;
        decided.insert(conversation, (Instant::now(), policy));
        policy
    }

    /// Conversations with a policy. For tests.
    pub fn tracked(&self) -> usize {
        self.decided.lock().map_or(0, |decided| decided.len())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    fn compacted(mut tool: Value) -> Value {
        compact_tool(&mut tool);
        tool
    }

    /// What a typed-model generator emits for a two-argument tool.
    fn generated() -> Value {
        json!({
            "name": "read_file",
            "description": "Read a file.",
            "input_schema": {
                "$schema": "https://json-schema.org/draft/2020-12/schema",
                "$id": "https://example.invalid/read_file.json",
                "title": "ReadFileArguments",
                "type": "object",
                "properties": {
                    "file_path": {"title": "File Path", "type": "string",
                                  "description": "The file to read.",
                                  "markdownDescription": "The **file** to read."},
                    "limit": {"title": "Limit", "type": "integer", "default": 2000,
                              "$comment": "kept in step with the reader"}
                },
                "required": ["file_path"],
                "additionalProperties": false
            }
        })
    }

    #[test]
    fn generated_bookkeeping_goes_and_everything_a_model_reads_stays() {
        assert_eq!(
            compacted(generated()),
            json!({
                "name": "read_file",
                "description": "Read a file.",
                "input_schema": {
                    "type": "object",
                    "properties": {
                        "file_path": {"type": "string", "description": "The file to read."},
                        "limit": {"type": "integer", "default": 2000}
                    },
                    "required": ["file_path"],
                    "additionalProperties": false
                }
            })
        );
    }

    #[test]
    fn it_is_idempotent_and_keeps_the_clients_key_order() {
        let once = compacted(generated());
        let mut twice = once.clone();
        assert!(!compact_tool(&mut twice), "nothing left to take");
        assert_eq!(twice, once);
        assert_eq!(
            serde_json::to_string(&once["input_schema"]).unwrap(),
            r#"{"type":"object","properties":{"file_path":{"type":"string","description":"The file to read."},"limit":{"type":"integer","default":2000}},"required":["file_path"],"additionalProperties":false}"#
        );
    }

    #[test]
    fn a_title_that_says_something_is_kept() {
        let tool = json!({"name": "search", "input_schema": {
            "title": "Search the index",
            "type": "object",
            "properties": {
                "q": {"title": "Query string, in Lucene syntax", "type": "string"},
                "max_results": {"title": "maxResults", "type": "integer"}
            }
        }});
        let out = compacted(tool);
        assert_eq!(out["input_schema"]["title"], "Search the index");
        assert_eq!(
            out["input_schema"]["properties"]["q"]["title"],
            "Query string, in Lucene syntax"
        );
        assert!(
            out["input_schema"]["properties"]["max_results"]
                .get("title")
                .is_none(),
            "another spelling of the name is still only the name"
        );
        // Punctuation is not spelling: these say what their names do not.
        let punctuated = json!({"name": "build", "input_schema": {"type": "object", "properties": {
            "c": {"title": "C++", "type": "boolean"},
            "io": {"title": "I/O", "type": "string"}
        }}});
        assert_eq!(compacted(punctuated.clone()), punctuated);
    }

    #[test]
    fn a_property_named_like_a_keyword_is_a_property() {
        let tool = json!({"name": "annotate", "input_schema": {
            "type": "object",
            "properties": {
                "title": {"type": "string", "description": "The note's title."},
                "$schema": {"type": "string"},
                "$comment": {"type": "string"},
                "markdownDescription": {"type": "string"}
            },
            "required": ["title"]
        }});
        assert_eq!(compacted(tool.clone()), tool);
    }

    #[test]
    fn values_are_the_tools_data_and_are_not_looked_into() {
        let tool = json!({"name": "configure", "input_schema": {
            "type": "object",
            "properties": {
                "settings": {
                    "type": "object",
                    "default": {"$schema": "x", "$comment": "y", "title": "settings"},
                    "examples": [{"$comment": "an example", "title": "t"}],
                    "enum": [{"$comment": "one"}],
                    "const": {"title": "settings", "$schema": "x"}
                }
            }
        }});
        assert_eq!(compacted(tool.clone()), tool);
    }

    #[test]
    fn nested_schemas_are_reached_and_names_inside_them_are_respected() {
        let tool = json!({"type": "function", "function": {"name": "plan", "parameters": {
            "type": "object",
            "properties": {
                "steps": {"type": "array", "items": {
                    "title": "Step",
                    "type": "object",
                    "$comment": "one step",
                    "properties": {"label": {"title": "Label", "type": "string"}}
                }},
                "mode": {"anyOf": [
                    {"type": "string", "$comment": "by name"},
                    {"type": "integer"}
                ]}
            },
            "$defs": {"title": {"type": "string", "$comment": "a definition named title"}}
        }}});
        let out = compacted(tool);
        let parameters = &out["function"]["parameters"];
        let step = &parameters["properties"]["steps"]["items"];
        assert_eq!(
            step["title"], "Step",
            "not the name of the property it describes"
        );
        assert!(step.get("$comment").is_none());
        assert!(step["properties"]["label"].get("title").is_none());
        assert!(
            parameters["properties"]["mode"]["anyOf"][0]
                .get("$comment")
                .is_none()
        );
        assert_eq!(parameters["$defs"]["title"], json!({"type": "string"}));
    }

    #[test]
    fn an_identifier_something_points_at_is_kept() {
        let mut tool = generated();
        tool["input_schema"]["properties"]["limit"] =
            json!({"$ref": "https://example.invalid/common.json#/limit"});
        let out = compacted(tool);
        assert!(
            out["input_schema"].get("$id").is_some(),
            "the reference resolves against it"
        );
        assert!(out["input_schema"].get("$schema").is_none());

        // A reference inside the document needs no identifier.
        let mut local = generated();
        local["input_schema"]["properties"]["limit"] = json!({"$ref": "#/$defs/limit"});
        assert!(compacted(local)["input_schema"].get("$id").is_none());
    }

    #[test]
    fn every_family_keeps_its_schema_where_this_looks() {
        let schema = json!({"$schema": "x", "type": "object"});
        let responses = json!({"type": "function", "name": "shell", "parameters": schema});
        assert_eq!(
            compacted(responses)["parameters"],
            json!({"type": "object"})
        );
        // A hosted tool has no schema, and a definition that is not an object
        // is not a definition.
        let hosted = json!({"type": "web_search_20250305", "name": "web_search"});
        assert_eq!(compacted(hosted.clone()), hosted);
        assert_eq!(compacted(json!("tool")), json!("tool"));
    }

    #[test]
    fn the_retrieve_tool_is_left_as_it_was_written() {
        let ours = json!({"name": RETRIEVE_TOOL_NAME, "input_schema": {"$schema": "x"}});
        let mut tools = vec![generated(), ours.clone(), compacted(generated())];
        assert_eq!(compact_tools(&mut tools), 1, "one had something to take");
        assert_eq!(tools[1], ours);
        assert_eq!(tools[0], tools[2]);
    }

    #[test]
    fn a_policy_is_decided_once_and_a_conversation_under_way_is_left_alone() {
        let policies = ToolPolicies::default();
        assert!(policies.compacting(1, 1, true));
        // The setting is turned off; the conversation keeps what it has.
        assert!(policies.compacting(1, 5, false));
        // First seen five messages in: the provider holds its tools as written.
        assert!(!policies.compacting(2, 5, true));
        assert!(!policies.compacting(2, 7, true));
        // Off when it opened, and off it stays.
        assert!(!policies.compacting(3, 1, false));
        assert!(!policies.compacting(3, 3, true));
        assert_eq!(policies.tracked(), 3);
    }

    /// Every key `after` lacks that `before` had, by the key's own name.
    fn removed_keys(before: &Value, after: &Value, into: &mut Vec<String>) {
        match (before, after) {
            (Value::Object(before), Value::Object(after)) => {
                for (key, item) in before {
                    match after.get(key) {
                        Some(kept) => removed_keys(item, kept, into),
                        None => into.push(key.clone()),
                    }
                }
            }
            (Value::Array(before), Value::Array(after)) => {
                assert_eq!(before.len(), after.len(), "no list changes length");
                for (item, kept) in before.iter().zip(after) {
                    removed_keys(item, kept, into);
                }
            }
            _ => assert_eq!(before, after, "no value is rewritten"),
        }
    }

    /// Over every tool definition in the committed Claude Code capture: the
    /// only difference compaction makes is the absence of keys it is allowed
    /// to take, and nothing else moves, is reordered or is reworded.
    #[test]
    fn on_real_tool_definitions_only_the_listed_keys_are_taken() {
        use std::io::Read;
        let path = concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../../fixtures/claude-capture.jsonl.gz"
        );
        let mut text = String::new();
        flate2::read::GzDecoder::new(std::fs::File::open(path).expect("the committed capture"))
            .read_to_string(&mut text)
            .expect("gzip");

        let mut seen = std::collections::BTreeSet::new();
        let (mut before_bytes, mut after_bytes, mut taken) = (0usize, 0usize, Vec::new());
        for line in text.lines() {
            let record: Value = serde_json::from_str(line).expect("a capture line");
            if record["dir"] != "client->proxy" {
                continue;
            }
            let Ok(body) = serde_json::from_str::<Value>(record["body"].as_str().unwrap_or(""))
            else {
                continue;
            };
            for tool in body["tools"].as_array().into_iter().flatten() {
                let written = serde_json::to_string(tool).unwrap();
                if !seen.insert(written.clone()) {
                    continue;
                }
                let after = compacted(tool.clone());
                removed_keys(tool, &after, &mut taken);
                before_bytes += written.len();
                after_bytes += serde_json::to_string(&after).unwrap().len();
                // What is left is the original with those keys absent, in the
                // original order: the kept keys are a subsequence.
                let kept: Vec<&String> = after["input_schema"]
                    .as_object()
                    .map(|object| object.keys().collect())
                    .unwrap_or_default();
                let original: Vec<&String> = tool["input_schema"]
                    .as_object()
                    .map(|object| object.keys().filter(|key| kept.contains(key)).collect())
                    .unwrap_or_default();
                assert_eq!(kept, original, "key order is the client's");
            }
        }
        assert!(seen.len() >= 10, "the capture carries Claude Code's tools");
        assert!(!taken.is_empty(), "and they have something to take");
        for key in &taken {
            assert!(
                ["$schema", "$comment", "$id", "markdownDescription", "title"]
                    .contains(&key.as_str()),
                "{key} is not ours to remove"
            );
        }
        // The measurement the setting's documentation quotes.
        let saved = (before_bytes - after_bytes) as f64 / before_bytes as f64;
        assert!(
            (0.015..0.03).contains(&saved),
            "{saved:.4} of {before_bytes} bytes"
        );
    }

    /// At the cap the conversation idle longest goes, not the one decided
    /// first: a long conversation still under way keeps its policy.
    #[test]
    fn a_conversation_still_in_use_is_not_the_one_evicted() {
        let policies = ToolPolicies::default();
        assert!(policies.compacting(0, 1, true));
        for conversation in 1..REMEMBER as u64 {
            policies.compacting(conversation, 1, true);
        }
        // The first one decided is used again, twenty messages in.
        std::thread::sleep(std::time::Duration::from_millis(2));
        assert!(policies.compacting(0, 20, true));
        // The table is full; the next arrival evicts someone else.
        policies.compacting(u64::MAX, 1, true);
        assert!(
            policies.compacting(0, 21, true),
            "still compacted: an entry lost here would be re-decided as under way"
        );
    }

    #[test]
    fn the_table_stays_bounded() {
        let policies = ToolPolicies::default();
        for conversation in 0..(REMEMBER as u64 + 16) {
            policies.compacting(conversation, 1, true);
        }
        assert_eq!(policies.tracked(), REMEMBER);
    }
}
